command:example.dev:code:
$log = New-ConsoleLogRegion -Height 5
$log | Add-ConsoleItem { [pscustomobject]@{ Message = 'Discovered 4 domain controllers'; AtSeconds = 2 } }
$log | Add-ConsoleItem { [pscustomobject]@{ Message = 'DC02 lags by 42 minutes'; Level = 'Warning'; AtSeconds = 31 } }
$log | Show-Console

$tree = New-ConsoleTree 'Shares'
foreach ($share in Get-SmbShare) {
    $tree | Add-ConsoleItem { [pscustomobject]@{ Label = $share.Name; Detail = $share.Path } }
}
$tree | Show-Console

It 'renders the report table' {
    $rows | Show-ConsoleTable -AsWidget | Assert-ConsoleOutput -GoldenPath "$PSScriptRoot\Golden\report.txt" -Width 80
}

$d = New-ConsoleDashboard -Title 'Patch' -Content { New-ConsolePanel -Title 'Servers' -Content { New-ConsoleLanes }; New-ConsolePanel -Title 'Log' -Fill -Content { New-ConsoleLogRegion } }
'SRV1', 'SRV2', 'SRV3' | Invoke-ConsoleDashboard $d -Parallel -ThrottleLimit 3 {
    param($Server)
    Update-Console lanes -Key $Server -Status Running -Total 5
    1..5 | ForEach-Object { Start-Sleep -Milliseconds 300; Update-Console lanes -Key $Server -Result Pass }
    Write-Host "$Server patched"
    Update-Console lanes -Key $Server -Complete
}

$frames = Get-Content ./frames.json | ConvertFrom-Json
function Show-Frame($Frame) { Update-Console cpu -Append -Value $Frame.Cpu }
Invoke-ConsoleDashboard $dashboard -ImportFunction Show-Frame { foreach ($frame in $using:frames) { Show-Frame $frame; Wait-ConsoleDashboard 0.5 } }

1..40 | Invoke-ConsoleRun -Parallel -ThrottleLimit 8 -TimeoutSeconds 10 -Title 'Patching web farm' -Label { "web$('{0:d2}' -f $_)" } {
    Start-Sleep -Milliseconds (Get-Random -Minimum 200 -Maximum 1500)
    if ($_ % 13 -eq 0) { throw "web$_ did not come back after the reboot" }
}

$dashboard = New-ConsoleDashboard -Title 'Checks' -Content { New-ConsolePanel -Title 'Running' -Content { New-ConsoleActivityList -WidgetId running -MaxVisible 4 } }
Invoke-ConsoleDashboard $dashboard {
    Update-Console -WidgetId running -Key 1 -Label 'SRV01 · Free space'
    Start-Sleep -Seconds 1
    Update-Console -WidgetId running -Key 1 -Complete
}

New-ConsoleColumns -FixedWidth 0, 0, 17 -CollapseBelow 90 -Content {
    New-ConsolePanel -Title 'Failures' -Weight 1.5 -Content { New-ConsoleTable -WidgetId failures -Live -Columns 'Server', 'Check' }
    New-ConsolePanel -Title 'Slowest' -Content { New-ConsoleTable -WidgetId slowest -Live -Columns 'Check', 'Took' }
    New-ConsolePanel -Title 'Durations' -Content { New-ConsoleChart -WidgetId durations -Height 5 -Type Histogram -Edges 0, 2, 4, 8 }
}

New-ConsoleField Servers 'Servers' -Type Select -Multiple -DependsOn Domain -ParameterName ComputerName -LoadChoices {
    param($Values)
    Get-AppServer -Domain $Values.Domain | ForEach-Object {
        [pscustomobject] @{ Name = $_.Name; Site = $_.Site; Role = $_.Role; Offline = $_.OfflineReason; Online = -not $_.OfflineReason }
    }
} -Display Name -CommandValue Name -GroupBy Site -Badge Role -DisabledReason Offline -Selected Online

New-ConsoleFlow -Content {
    [pscustomobject] @{ Kind = 'Node'; Key = 'leaf'; Label = 'Leaf'; Status = 'Pass' }
    [pscustomobject] @{ Kind = 'Node'; Key = 'issuer'; Label = 'Intermediate'; Status = 'Fail' }
    [pscustomobject] @{ Kind = 'Edge'; Key = 'chain'; From = 'leaf'; To = 'issuer'; Label = 'expired'; Status = 'Fail'; Cut = $true }
}

$form = New-ConsoleForm 'New share' -Command 'New-AppShare' -PageDescriptions @{ Basics = 'Name and location of the share.'; Access = 'How people can use the share.' } -Content {
    New-ConsoleField Name 'Share name' -Page Basics -Required -ParameterName Name
    New-ConsoleField Path 'Folder' -Type Path -Kind Folder -MustExist -Page Basics -ParameterName Path
    New-ConsoleField ReadOnly 'Read only' -Type Toggle -Page Access -ParameterName ReadOnly
}

$form = New-ConsoleForm 'New share' -Command 'New-AppShare' -Content {
    New-ConsoleField Name 'Share name' -Required -ParameterName Name
    New-ConsoleField ReadOnly 'Read only' -Type Toggle -ParameterName ReadOnly
    [pscustomobject]@{ Name = 'Archive'; Values = @{ Name = 'Archive'; ReadOnly = $true }; Description = 'A read-only archive share.' }
}

New-ConsoleKeyValue -Content {
    [pscustomobject]@{ Key = 'Version'; Value = '0.0.4 [muted]→[/] [bold]2.0.0[/]'; Markup = $true }
    [pscustomobject]@{ Key = 'Signing'; Value = 'skipped'; Status = 'Skip' }
    [pscustomobject]@{ Key = 'Tests'; Value = '1 skipped on PowerShell 7'; Status = 'Warn' }
} | Show-Console

New-ConsoleKeyValue -InputObject ([ordered] @{ Module = 'ConsoleMonster'; Frameworks = 'netstandard2.0, net472, net8.0' }) -Content {
    [pscustomobject]@{ Key = 'Signing'; Value = 'skipped'; Status = 'Skip' }
} | Show-Console

New-ConsoleLanes -Content {
    [pscustomobject]@{ Key = 'DC01'; Total = 40; Status = 'Pass'; Passed = 40; Value = 40 }
    [pscustomobject]@{ Key = 'DC02'; Total = 40; Status = 'Running'; Passed = 21; Warned = 1; Detail = 'replication'; Value = 22 }
    [pscustomobject]@{ Key = 'DC03'; Total = 40 }
} | Show-Console

New-ConsoleLogRegion -Height 5 -Content {
    [pscustomobject]@{ Message = 'Discovered 4 domain controllers in 2 domains'; Level = 'Info'; AtSeconds = 2 }
    [pscustomobject]@{ Message = 'DC02: USN rollback check failed (event 2095)'; Level = 'Error'; AtSeconds = 44 }
    [pscustomobject]@{ Message = 'Using cached schema snapshot'; Level = 'Verbose'; AtSeconds = 53 }
} | Show-Console

$menu = New-ConsoleMenu 'Backup helper' -Content {
    New-ConsoleMenuItem 'Back up now' -Hotkey b -Action { Start-Backup }
    New-ConsoleMenuItem 'Settings' -Hotkey s -Form $settings
    New-ConsoleMenuItem -Exit
}
Show-ConsoleMenu $menu -Layout Classic

$menu = New-ConsoleMenu 'Backup helper' -Content {
    [pscustomobject]@{ Name = 'Weekly'; Form = $settings; Values = @{ Target = 'Weekly'; Compress = $true }; Description = 'The Sunday backup.' }
    New-ConsoleMenuItem 'Presets' -Hotkey p -Presets
    New-ConsoleMenuItem 'Settings' -Hotkey s -Form $settings
    New-ConsoleMenuItem -Exit
}
Show-ConsoleMenu $menu -Layout Shell

New-ConsoleMenuItem 'Back up now' -Action {
    $dashboard = New-ConsoleDashboard -Title 'Backup' -Content { New-ConsoleStatusList -Item 'Scan files', 'Copy changes' }
    $null = $MenuContext.Run($dashboard, {
        Update-Console status -Key 'Scan files' -Status Pass
        Update-Console status -Key 'Copy changes' -Status Pass
        New-ConsoleMenuRunResult 'Backup finished' -Summary '1 284 files copied, 312 MB.' -Figure ([ordered] @{ files = '1 284'; copied = '312 MB' }) -Next @{
            'Show where the log is' = { $MenuContext.Toast('Log: D:\Backups\backup.log') }
        }
    })
}

New-ConsolePhases -Content {
    [pscustomobject]@{ Label = 'Discover'; Status = 'Pass'; Detail = '2.1s' }
    [pscustomobject]@{ Label = 'Collect'; Status = 'Pass'; Detail = '14s' }
    [pscustomobject]@{ Label = 'Evaluate'; Status = 'Running'; Detail = '64%' }
    [pscustomobject]@{ Label = 'Report' }
} | Show-Console

New-ConsoleMenuItem 'Run checks' -Action {
    $clock = New-ConsoleSimulatedClock -Speed 7
    $dashboard = New-ConsoleDashboard -Title 'Checks' -Content { New-ConsoleSummaryBar -Total 3; New-ConsoleLogRegion -Height 5 }
    $null = $MenuContext.Run($dashboard, {
        foreach ($done in 1..3) {
            $clock.Wait(4.5)
            Update-Console -Counter @{ passed = $done } -WidgetId 'summary' -Value $done
            Write-ConsoleLogEntry "Check $done passed"
        }
        New-ConsoleMenuRunResult 'Checks finished'
    }, $clock)
}

$clock = New-ConsoleSimulatedClock -Speed 10
Invoke-ConsoleDashboard $dashboard -Clock $clock -ArgumentList $clock, $entries {
    param($Clock, $Entries)
    foreach ($entry in $Entries) { $Clock.WaitUntil($entry.Seconds); Write-ConsoleLogEntry $entry.Text }
}

New-ConsoleStack -Content {
    New-ConsoleChart -WidgetId latency -Type Line
    New-ConsoleAlign -Horizontal Right -Content { New-ConsoleText -Markup '[pass]LIVE[/]' }
}

New-ConsoleStatusList -Content {
    [pscustomobject]@{ Label = 'Restore NuGet packages'; Status = 'Pass'; Detail = '1.6 s' }
    [pscustomobject]@{ Label = 'Compile ConsoleMonster'; Status = 'Pass'; Detail = '4.7 s' }
    [pscustomobject]@{ Label = 'Run Pester on PowerShell 7'; Status = 'Warn'; Detail = '1 skipped' }
    [pscustomobject]@{ Label = 'Pack ConsoleMonster.2.0.0.nupkg'; Status = 'Running' }
} | Show-Console

New-ConsoleTree '[bold]evotec.xyz[/]' -Content {
    [pscustomobject]@{ Label = 'MX'; Status = 'Pass'; Detail = '2 records'; Children = @(& {
        [pscustomobject]@{ Label = 'evotec-xyz.mail.protection.outlook.com'; Detail = 'priority 0' }
    }) }
    [pscustomobject]@{ Label = 'SPF'; Status = 'Warn'; Detail = '9 of 10 DNS lookups'; Children = @(& {
        'include:spf.protection.outlook.com'
        'include:_spf.salesforce.com'
    }) }
    [pscustomobject]@{ Label = 'DMARC'; Status = 'Fail'; Detail = 'p=none' }
} | Show-Console

$groups = @(
    [pscustomobject] @{ Name = 'Domain Admins'; Health = 'Warn'; Note = '6 members'; Members = @(
        [pscustomobject] @{ Name = 'Tier 0 operators'; Health = 'Pass'; Members = @([pscustomobject] @{ Name = 'anna.k' }) }
        [pscustomobject] @{ Name = 'svc-backup'; Health = 'Fail'; Note = 'password never expires' }
    ) }
)
$groups | New-ConsoleTree 'Privileged groups' -ChildrenProperty Members -StatusProperty Health -DetailProperty Note | Show-Console

$form = New-ConsoleForm 'Example' -Content { New-ConsoleField Name 'Name' -Default 'example' }
$answers = Read-ConsoleForm $form
if ($answers) { Write-Host "Selected $($answers.Name)" }

Show-ConsoleApp -Content {
                New-ConsoleTextInput -Key Query -OnChange { param($Value, $State) $State.Edits = 1 + $State.Edits }
                New-ConsoleTable -Bind { $services | Where-Object Name -Like "*$($State.Query)*" } -Property Name, Status
                New-ConsoleBinding -Content { "Edits: $($State.Edits)" }
            } -PassThru

$files = @(Get-ChildItem *.log)
$run = Start-ConsoleRun -Items $files -Title 'Archive logs' -Label Name -Target DirectoryName
try {
    for ($i = 0; $i -lt $files.Count; $i++) {
        Update-Console -Run $run -Index $i -Status Running -Label 'archiving'
        try { Compress-Archive $files[$i].FullName "$($files[$i].FullName).zip" -ErrorAction Stop; Update-Console -Run $run -Index $i -Status Pass }
        catch { Update-Console -Run $run -Index $i -Status Fail -Detail $_.Exception.Message }
    }
} finally { Complete-ConsoleRun $run }

Use-ConsoleProgress {
    foreach ($i in 1..50) {
        Write-Progress -Activity 'Copying' -Status "File $i of 50" -PercentComplete ($i * 2)
        Start-Sleep -Milliseconds 50
    }
}

$dashboard = New-ConsoleDashboard -Title 'Scan' -Content {
    New-ConsoleProgress -WidgetId overall -Label Targets -Total 3
}
Invoke-ConsoleDashboard -Dashboard $dashboard -ScriptBlock {
    foreach ($count in 1..3) {
        Update-Console -WidgetId overall -Value $count
        Wait-ConsoleDashboard -Seconds 0.25
    }
}
